package com.autocare.platform.order;
import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.vehicle.VehicleOwner;
import com.fasterxml.jackson.databind.JsonNode;
import java.time.Instant;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static com.autocare.platform.order.ReservationStore.*;

/** Policy configuration only. Publishing does not reserve stock or issue coupons. */
public class InviteRewardPolicies {
 public static final String RULE="R6B_REWARD_V1";
 private final ReservationStore db;private final OperatorIdentity operators;private final CouponInventory coupons;
 public InviteRewardPolicies(ReservationStore db,OperatorIdentity operators,CouponInventory coupons){this.db=db;this.operators=operators;this.coupons=coupons;}
 static ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"邀请规则或券来源已变化，请刷新");}
 Map<String,Object> row(long id,boolean lock){return db.one("SELECT * FROM invite_reward_policy WHERE id=?"+(lock?" FOR UPDATE":""),id);}
 Map<String,Object> view(Map<String,Object> r){var n=new LinkedHashMap<String,Object>();for(String k:List.of("id","scope","revision","status","source_note","inviter_coupon_id","inviter_publication_revision","invitee_coupon_id","invitee_publication_revision","rule_version"))n.put(k,r.get(k));n.put("valid_from",iso(r.get("valid_from")));n.put("valid_to",iso(r.get("valid_to")));n.put("created_at",iso(r.get("created_at")));n.put("published_at",iso(r.get("published_at")));n.put("inviter_terms",db.parse(r.get("inviter_terms_json")));n.put("invitee_terms",db.parse(r.get("invitee_terms_json")));return n;}
 public Map<String,Object> list(OperatorActor a,int p){return db.reads.execute(t->{operators.authorize(a,OperatorIdentity.Permission.INVITE,false);long count=db.jdbc.queryForObject("SELECT COUNT(*) FROM invite_reward_policy",Long.class);return page(db.jdbc.queryForList("SELECT * FROM invite_reward_policy ORDER BY id DESC LIMIT 20 OFFSET ?",(p-1)*20L).stream().map(this::view).toList(),count,p,20);});}
 public Map<String,Object> offers(OperatorActor a,int p){return db.reads.execute(t->{operators.authorize(a,OperatorIdentity.Permission.INVITE,false);return coupons.list("c.status='PUBLISHED' AND c.is_deleted=0 AND s.pool_selected=1 AND p.coupon_id IS NOT NULL AND c.valid_to>? AND EXISTS(SELECT 1 FROM merchant m WHERE m.id=c.merchant_id AND m.status=1 AND m.is_deleted=0) AND EXISTS(SELECT 1 FROM standard_project sp WHERE sp.id=s.project_id AND sp.status=1 AND sp.is_deleted=0) AND EXISTS(SELECT 1 FROM merchant_project mp WHERE mp.merchant_id=c.merchant_id AND mp.project_id=s.project_id AND mp.on_shelf=1 AND mp.is_deleted=0)",List.of(time(db.now())),p,20);});}
 private void references(JsonNode b,boolean lock){var ids=new TreeMap<Long,Long>();long invited=b.get("invitee_coupon_id").longValue(),version=b.get("invitee_publication_revision").longValue();ids.put(invited,version);if(!b.get("inviter_coupon_id").isNull()){long id=b.get("inviter_coupon_id").longValue(),v=b.get("inviter_publication_revision").longValue();if(ids.containsKey(id)&&ids.get(id)!=v)throw conflict();ids.put(id,v);}
  if(lock){var shops=new TreeSet<Long>();var projects=new TreeSet<Long>();for(long id:ids.keySet()){var r=coupons.row(id,false);if(!"PUBLISHED".equals(r.get("status")))throw conflict();shops.add(number(r,"merchant_id"));projects.add(number(r,"project_id"));}for(long id:shops)db.lockShop(id);for(long id:projects)db.one("SELECT id FROM standard_project WHERE id=? FOR UPDATE",id);}
  for(var e:ids.entrySet())validSource(e.getKey(),e.getValue(),CouponInput.time(b.get("valid_from")),CouponInput.time(b.get("valid_to")),lock);}
 private Map<String,Object> validSource(long id,long revision,Instant from,Instant to,boolean lock){var r=coupons.source(id,lock);if(!"PUBLISHED".equals(r.get("status"))||r.get("publication_revision")==null||number(r,"publication_revision")!=revision||number(r,"pool_selected")!=1||instant(r.get("valid_from")).isAfter(from)||instant(r.get("valid_to")).isBefore(to)||!db.parse(r.get("terms_json")).equals(db.parse(r.get("published_terms"))))throw conflict();return r;}
 public JsonNode create(OperatorActor a,String key,JsonNode b){return db.writes.execute(new Actor("operator_account",a.id()),"POST","/api/admin/invite/reward-policies",key,b,()->{operators.authorize(a,OperatorIdentity.Permission.INVITE,true);references(b,true);},()->{if(!CouponInput.time(b.get("valid_to")).isAfter(db.now()))throw conflict();long id=db.insert("INSERT INTO invite_reward_policy(scope,source_note,valid_from,valid_to,inviter_coupon_id,inviter_publication_revision,invitee_coupon_id,invitee_publication_revision,rule_version,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",b.get("scope").textValue(),b.get("source_note").textValue(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),nullable(b.get("inviter_coupon_id")),nullable(b.get("inviter_publication_revision")),b.get("invitee_coupon_id").longValue(),b.get("invitee_publication_revision").longValue(),RULE,a.id(),time(db.now()));var after=view(row(id,true));return new Change("INVITE_POLICY_CREATE","invite_reward_policy",id,Map.of(),after,after);});}
 static Object nullable(JsonNode n){return n.isNull()?null:n.longValue();}
 public JsonNode update(OperatorActor a,long id,String key,JsonNode b){return db.writes.execute(new Actor("operator_account",a.id()),"PUT","/api/admin/invite/reward-policies/"+id,key,b,()->{operators.authorize(a,OperatorIdentity.Permission.INVITE,true);references(b,true);row(id,true);},()->{var r=row(id,true);if(!"DRAFT".equals(r.get("status"))||number(r,"revision")!=b.get("expected_revision").longValue()||!CouponInput.time(b.get("valid_to")).isAfter(db.now()))throw conflict();var before=view(r);db.jdbc.update("UPDATE invite_reward_policy SET scope=?,source_note=?,valid_from=?,valid_to=?,inviter_coupon_id=?,inviter_publication_revision=?,invitee_coupon_id=?,invitee_publication_revision=?,revision=revision+1 WHERE id=?",b.get("scope").textValue(),b.get("source_note").textValue(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),nullable(b.get("inviter_coupon_id")),nullable(b.get("inviter_publication_revision")),b.get("invitee_coupon_id").longValue(),b.get("invitee_publication_revision").longValue(),id);var after=view(row(id,true));return new Change("INVITE_POLICY_UPDATE","invite_reward_policy",id,before,after,after);});}
 public JsonNode status(OperatorActor a,long id,String key,JsonNode b){return db.writes.execute(new Actor("operator_account",a.id()),"PUT","/api/admin/invite/reward-policies/"+id+"/status",key,b,()->{operators.authorize(a,OperatorIdentity.Permission.INVITE,true);var r=row(id,false);if("PUBLISHED".equals(b.path("status").asText()))references(db.mapper.valueToTree(view(r)),true);row(id,true);},()->{var r=row(id,true);String target=b.get("status").textValue();if(number(r,"revision")!=b.get("expected_revision").longValue()||!(target.equals("PUBLISHED")?"DRAFT".equals(r.get("status")):"PUBLISHED".equals(r.get("status"))))throw conflict();var before=view(r);if(target.equals("PUBLISHED")){if(!instant(r.get("valid_to")).isAfter(db.now())||!db.jdbc.queryForList("SELECT id FROM invite_reward_policy WHERE scope=? AND status='PUBLISHED'",r.get("scope")).isEmpty())throw conflict();Map<String,Object> inviter=r.get("inviter_coupon_id")==null?null:coupons.row(number(r,"inviter_coupon_id"),true),invitee=coupons.row(number(r,"invitee_coupon_id"),true);try{db.jdbc.update("UPDATE invite_reward_policy SET status='PUBLISHED',revision=revision+1,inviter_terms_json=?,invitee_terms_json=?,published_at=? WHERE id=?",inviter==null?null:inviter.get("published_terms").toString(),invitee.get("published_terms").toString(),time(db.now()),id);}catch(org.springframework.dao.DuplicateKeyException e){throw conflict();}}else db.jdbc.update("UPDATE invite_reward_policy SET status='STOPPED',revision=revision+1 WHERE id=?",id);var after=view(row(id,true));return new Change("INVITE_POLICY_STATUS","invite_reward_policy",id,before,after,after);});}
 public Map<String,Object> current(VehicleOwner a,String scope){return db.reads.execute(t->{db.owner(a,false);var rows=db.jdbc.queryForList("SELECT * FROM invite_reward_policy WHERE scope=? AND status='PUBLISHED'",scope);var out=new LinkedHashMap<String,Object>();out.put("scope",scope);out.put("policy",null);out.put("state","UNKNOWN");if(rows.isEmpty())return out;var r=rows.get(0);String state=instant(r.get("valid_from")).isAfter(db.now())?"NOT_STARTED":!instant(r.get("valid_to")).isAfter(db.now())?"EXPIRED":"CONFIGURED";try{if(state.equals("CONFIGURED"))references(db.mapper.valueToTree(view(r)),false);}catch(ResponseStatusException e){state="SOURCE_UNAVAILABLE";}var n=view(r);n.remove("source_note");out.put("policy",n);out.put("state",state);return out;});}
}
